/** Function memoization with instance-local caches. */
import type { MemoizeOptions, MemoizedFunction } from "../core/types.js";
import { CacheFn } from "../core/cache.js";
import { StatsTracker } from "../analytics/stats.js";
import { generateKey } from "../utils/hash.js";
import { calculateExpiration } from "../strategies/ttl-manager.js";

export type AsyncMemoized<T extends (...args: any[]) => any> =
  ((this: ThisParameterType<T>, ...args: Parameters<T>) => Promise<Awaited<ReturnType<T>>>) & MemoizedFunction;

let instanceId = 0;

function capacity(value = 1000): number {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError("maxSize must be a non-negative safe integer");
  }
  return value;
}

/** Always returns a Promise, including when the original function is synchronous. */
export function memoize<T extends (...args: any[]) => any>(
  fn: T,
  options?: MemoizeOptions<T>
): AsyncMemoized<T> {
  const maxSize = capacity(options?.maxSize);
  const cache = new CacheFn<{ value: Awaited<ReturnType<T>> }>({
    // Function names are not unique; persistent backends must also be isolated.
    name: `memoize-${Date.now()}-${++instanceId}-${Math.random().toString(36).slice(2)}`,
    storage: options?.storage ?? "memory",
    maxSize,
    defaultTTL: options?.ttl,
  });
  const keyGenerator = options?.keyGenerator ??
    ((...args: Parameters<T>) => generateKey(fn.name || "fn", args));
  const pending = new Map<string, object>();
  const flights = new Map<string, Promise<Awaited<ReturnType<T>>>>();

  const memoized = function (this: ThisParameterType<T>, ...args: Parameters<T>) {
    const key = keyGenerator(...args);
    const existing = flights.get(key);
    if (existing) return existing;
    const token = {};
    pending.set(key, token);
    const result = (async (): Promise<Awaited<ReturnType<T>>> => {
      const cached = await cache.get(key);
      if (cached !== undefined && pending.get(key) === token) return cached.value;
      const value: Awaited<ReturnType<T>> = await fn.apply(this, args);
      // Invalidation must not allow an earlier computation to repopulate the cache.
      if (maxSize > 0 && pending.get(key) === token) {
        await cache.set(key, { value }, { tags: options?.tags });
      }
      return value;
    })();
    flights.set(key, result);
    const cleanup = () => {
      if (pending.get(key) === token) {
        pending.delete(key);
        flights.delete(key);
      }
    };
    result.then(cleanup, cleanup);
    return result;
  };
  memoized.clear = async () => {
    pending.clear();
    flights.clear();
    await cache.clear();
  };
  memoized.delete = async (...args: Parameters<T>) => {
    const key = keyGenerator(...args);
    pending.delete(key);
    flights.delete(key);
    await cache.delete(key);
  };
  memoized.stats = () => cache.getStats();
  return memoized;
}

/** Synchronous, memory-only memoization with TTL and LRU eviction. */
export function memoizeSync<T extends (...args: any[]) => any>(
  fn: T,
  options?: MemoizeOptions<T>
): T & MemoizedFunction {
  if (options?.storage && options.storage !== "memory") {
    throw new TypeError("memoizeSync supports only memory storage");
  }
  const maxSize = capacity(options?.maxSize);
  const cache = new Map<string, { value: ReturnType<T>; expiresAt?: number }>();
  const stats = new StatsTracker();
  const keyGenerator = options?.keyGenerator ??
    ((...args: Parameters<T>) => generateKey(fn.name || "fn", args));
  const prune = () => {
    const now = Date.now();
    for (const [key, entry] of cache) {
      if (entry.expiresAt !== undefined && now >= entry.expiresAt) cache.delete(key);
    }
  };
  const memoized = function (this: ThisParameterType<T>, ...args: Parameters<T>): ReturnType<T> {
    const key = keyGenerator(...args);
    prune();
    const entry = cache.get(key);
    if (entry) {
      cache.delete(key);
      cache.set(key, entry);
      stats.recordHit();
      return entry.value;
    }
    stats.recordMiss();
    const value = fn.apply(this, args);
    if (maxSize > 0) {
      // Re-entrant calls may have filled the cache while computing this result.
      cache.delete(key);
      while (cache.size >= maxSize) {
        cache.delete(cache.keys().next().value!);
        stats.recordEviction();
      }
      cache.set(key, { value, expiresAt: calculateExpiration(options?.ttl) });
      stats.recordSet();
    }
    return value;
  };
  memoized.clear = async () => { cache.clear(); stats.reset(); };
  memoized.delete = async (...args: Parameters<T>) => {
    if (cache.delete(keyGenerator(...args))) stats.recordDelete();
  };
  memoized.stats = async () => { prune(); return stats.getStats(cache.size); };
  return memoized as T & MemoizedFunction;
}
/**
 * Main CacheFn class
 */

import type {
  CacheFnConfig,
  SetOptions,
  CacheStats,
  StorageType,
  EventHandler,
} from "./types.js";
import type { StorageBackend } from "../storage/storage-interface.js";
import { MemoryStorage } from "../storage/memory-storage.js";
import { IndexedDBStorage } from "../storage/indexeddb-storage.js";
import { EventEmitter } from "./events.js";
import { StatsTracker } from "../analytics/stats.js";
import { calculateExpiration } from "../strategies/ttl-manager.js";
import { filterByPattern } from "../utils/pattern.js";

/**
 * CacheFn - Self-hosted caching solution
 */
export class CacheFn<T = any> {
  private storage: StorageBackend<T>;
  private events: EventEmitter;
  private stats: StatsTracker;
  private defaultTTL?: number;
  private namespace?: string;
  private pending = new Map<string, Promise<T>>();

  constructor(config: CacheFnConfig) {
    this.defaultTTL = config.defaultTTL;
    this.namespace = config.namespace;
    this.events = new EventEmitter();
    this.stats = new StatsTracker();

    // Initialize storage backend
    const storageType = config.storage ?? "memory";
    this.storage = this.createStorage(storageType, config);
  }

  /**
   * Get a value from cache
   */
  async get(key: string): Promise<T | undefined> {
    const fullKey = this.getFullKey(key);
    const startTime = performance.now();

    const value = await this.storage.get(fullKey);
    const accessTime = performance.now() - startTime;

    if (value !== undefined || await this.storage.has(fullKey)) {
      this.stats.recordHit();
      this.events.emit("hit", { key: this.eventKey(key), accessTime });
    } else {
      this.stats.recordMiss();
      this.events.emit("miss", { key: this.eventKey(key) });
    }

    return value;
  }

  /**
   * Set a value in cache
   */
  async set(key: string, value: T, options?: SetOptions): Promise<void> {
    const fullKey = this.getFullKey(key);
    this.pending.delete(fullKey);
    const ttl = options?.ttl ?? this.defaultTTL;

    const metadata = {
      createdAt: Date.now(),
      expiresAt: calculateExpiration(ttl),
      tags: options?.tags,
      hits: 0,
      lastAccess: Date.now(),
    };

    await this.storage.set(fullKey, value, metadata);

    this.stats.recordSet();
    this.events.emit("set", { key: this.eventKey(key), size: 1 });
  }

  /**
   * Check if a key exists in cache
   */
  async has(key: string): Promise<boolean> {
    const fullKey = this.getFullKey(key);
    return await this.storage.has(fullKey);
  }

  /**
   * Delete a value from cache
   */
  async delete(key: string): Promise<boolean> {
    const fullKey = this.getFullKey(key);
    this.pending.delete(fullKey);
    const deleted = await this.storage.delete(fullKey);

    if (deleted) {
      this.stats.recordDelete();
      this.events.emit("delete", { key: this.eventKey(key) });
    }

    return deleted;
  }

  /**
   * Clear all values from cache
   */
  async clear(): Promise<void> {
    this.pending.clear();
    const keys = (await this.storage.keys()).filter((key) => this.ownsKey(key));
    await Promise.all(keys.map((key) => this.storage.delete(key)));
    this.stats.reset();
  }

  /**
   * Get multiple values from cache
   */
  async getMany(keys: string[]): Promise<Array<T | undefined>> {
    return Promise.all(keys.map((key) => this.get(key)));
  }

  /**
   * Set multiple values in cache
   */
  async setMany(
    entries: Array<{ key: string; value: T; options?: SetOptions }>
  ): Promise<void> {
    await Promise.all(
      entries.map((entry) => this.set(entry.key, entry.value, entry.options))
    );
  }

  /**
   * Delete multiple values from cache
   */
  async deleteMany(keys: string[]): Promise<void> {
    await Promise.all(keys.map((key) => this.delete(key)));
  }

  /**
   * Get all keys matching a pattern
   */
  async keys(pattern?: string): Promise<string[]> {
    const allKeys = await this.storage.keys();

    const keysWithoutNamespace = allKeys.filter((key) => this.ownsKey(key))
      .map((key) => key.slice(this.keyPrefix().length));

    return filterByPattern(keysWithoutNamespace, pattern);
  }

  /**
   * Get the number of entries in cache
   */
  async size(): Promise<number> {
    return (await this.keys()).length;
  }

  /**
   * Get or fetch a value (cache-aside pattern)
   */
  getOrFetch(
    key: string,
    fetcher: () => Promise<T>,
    options?: SetOptions
  ): Promise<T> {
    const fullKey = this.getFullKey(key);
    const existing = this.pending.get(fullKey);
    if (existing) return existing;
    // Register before any await so invalidation also cancels a pending lookup.
    const task = Promise.resolve().then(async () => {
      const cached = await this.get(key);
      if (cached !== undefined || await this.has(key)) return cached as T;
      const value = await fetcher();
      if (this.pending.get(fullKey) === task) await this.set(key, value, options);
      return value;
    }).finally(() => {
      if (this.pending.get(fullKey) === task) this.pending.delete(fullKey);
    });
    this.pending.set(fullKey, task);
    return task;
  }

  /**
   * Invalidate a single key (alias for delete)
   */
  async invalidate(key: string): Promise<boolean> {
    return await this.delete(key);
  }

  /**
   * Invalidate all keys with a specific tag
   */
